const crypto = require('crypto');

const GDPR_SECRET = $env.PERSONA_GDPR_SECRET || 'change-me-in-production';
const token = $json.query?.token || '';
const actionParam = $json.query?.action || '';

function verifyGdprToken(tokenStr) {
  const parts = (tokenStr || '').split('.');
  if (parts.length !== 2) return { valid: false, error: 'Lien invalide.' };
  const [payload, sig] = parts;
  const expected = crypto.createHmac('sha256', GDPR_SECRET).update(payload).digest('base64url');
  if (sig !== expected) return { valid: false, error: 'Signature invalide.' };
  try {
    const data = JSON.parse(Buffer.from(payload, 'base64url').toString());
    if (Date.now() > data.exp) return { valid: false, error: 'Ce lien a expire (72h). Utilisez le chatbot.' };
    if (actionParam && data.action !== actionParam) return { valid: false, error: 'Action non autorisee.' };
    return { valid: true, userId: data.userId, action: data.action };
  } catch (e) {
    return { valid: false, error: 'Token corrompu.' };
  }
}

const verified = verifyGdprToken(token);
return { json: { ...verified, token, ip: $json.headers?.['x-forwarded-for'] || 'webhook' } };

const action = $('Verify Token').first().json.action;
const result = $('Execute GDPR').first().json;

const titles = {
  unsubscribe: 'Desinscription confirmee',
  export: 'Export de vos donnees',
  delete: 'Compte supprime'
};

const messages = {
  unsubscribe: 'Vous ne recevrez plus de newsletter Persona. Votre compte reste actif.',
  export: result.data ? JSON.stringify(result.data, null, 2) : 'Donnees exportees.',
  delete: 'Toutes vos donnees personnelles ont ete supprimees conformement au RGPD (Art. 17).'
};

const ok = result.success !== false;
const title = ok ? (titles[action] || 'Action RGPD') : 'Erreur';
const msg = ok ? (messages[action] || 'Action effectuee.') : (result.error || 'Action impossible.');

const dataBlock = action === 'export' && ok && result.data
  ? `<pre style="background:#f5f5f5;padding:16px;border-radius:8px;overflow:auto;text-align:left;font-size:12px;">${JSON.stringify(result.data, null, 2).replace(/</g,'&lt;')}</pre>`
  : `<p style="color:#555;line-height:1.6;">${msg.replace(/</g,'&lt;')}</p>`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${title} - Persona</title></head>
<body style="font-family:Arial,sans-serif;max-width:560px;margin:40px auto;padding:24px;background:#f5f5f5;">
  <div style="background:white;border-radius:12px;padding:32px;box-shadow:0 4px 20px rgba(0,0,0,0.08);">
    <div style="text-align:center;margin-bottom:24px;">
      <div style="font-size:48px;">${ok ? '✓' : '✗'}</div>
      <h1 style="color:#1A3A6B;margin:8px 0;">${title}</h1>
    </div>
    ${dataBlock}
    <p style="color:#999;font-size:12px;text-align:center;margin-top:24px;">Persona — Lien signe HMAC-SHA256 · Conforme RGPD</p>
  </div>
</body></html>`;

return { json: { html, statusCode: ok ? 200 : 400 } };

const err = $json.error || 'Lien invalide.';
const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;max-width:560px;margin:40px auto;padding:32px;text-align:center;">
<h1 style="color:#c0392b;">Lien invalide</h1><p>${err}</p>
<p style="color:#999;font-size:13px;">Utilisez le chatbot Persona (commande rgpd).</p></body></html>`;
return { json: { html, statusCode: 403 } };
